mainStatements.template:
module kvMainModule '{{moduleReference}}' = if (kvMain.deploy && logMain.deploy) {
  name: 'kvMain-${uniqueString(kvMain.name)}'
  scope: rg_main
  params: {
    name: kvMain.name
    location: kvMain.location
    enablePurgeProtection: kvMain.enablePurgeProtection
    enableRbacAuthorization: kvMain.enableRbacAuthorization
    enableSoftDelete: kvMain.enableSoftDelete
    softDeleteRetentionInDays: kvMain.softDeleteRetentionInDays
    sku: kvMain.sku
    publicNetworkAccess: kvMain.publicNetworkAccess
    accessPolicies: []
    secrets: []
    keys: []
    tags: kvMain.tags
    diagnosticSettings: [
      for setting in kvMain.diagnosticSettings: {
        name: setting.name
        workspaceResourceId: resourceId(
          target.subscriptionId,
          resourceGroups.main.name,
          'Microsoft.OperationalInsights/workspaces',
          logMain.name
        )
        logAnalyticsDestinationType: setting.logAnalyticsDestinationType
        logCategoriesAndGroups: [
          {
            categoryGroup: setting.logCategoryGroup
            enabled: true
          }
        ]
        metricCategories: [
          {
            category: setting.metricCategory
            enabled: true
          }
        ]
      }
    ]
    enableTelemetry: false
  }
  dependsOn: [
    logMainModule
  ]
}

mainStatements.restrictedTemplate:
module kvMainModule '{{moduleReference}}' = if (kvMain.deploy && logMain.deploy) {
  name: 'kvMain-${uniqueString(kvMain.name)}'
  scope: rg_main
  params: {
    name: kvMain.name
    location: kvMain.location
    enablePurgeProtection: kvMain.enablePurgeProtection
    enableRbacAuthorization: kvMain.enableRbacAuthorization
    enableSoftDelete: kvMain.enableSoftDelete
    softDeleteRetentionInDays: kvMain.softDeleteRetentionInDays
    sku: kvMain.sku
    publicNetworkAccess: kvMain.publicNetworkAccess
    networkAcls: {
      bypass: kvMain.exposure == 'Restricted' ? 'None' : 'AzureServices'
      defaultAction: kvMain.exposure == 'Restricted' ? 'Deny' : 'Allow'
      ipRules: [
        for ipRange in kvMain.allowedIpRanges: {
          value: ipRange
        }
      ]
      virtualNetworkRules: []
    }
    accessPolicies: []
    secrets: []
    keys: []
    tags: kvMain.tags
    diagnosticSettings: [
      for setting in kvMain.diagnosticSettings: {
        name: setting.name
        workspaceResourceId: resourceId(
          target.subscriptionId,
          resourceGroups.main.name,
          'Microsoft.OperationalInsights/workspaces',
          logMain.name
        )
        logAnalyticsDestinationType: setting.logAnalyticsDestinationType
        logCategoriesAndGroups: [
          {
            categoryGroup: setting.logCategoryGroup
            enabled: true
          }
        ]
        metricCategories: [
          {
            category: setting.metricCategory
            enabled: true
          }
        ]
      }
    ]
    enableTelemetry: false
  }
  dependsOn: [
    logMainModule
  ]
}

mainStatements.template:
module deploymentSecretsOfficer './key-vault-role-assignment.bicep' = if (kvMain.deploy && !empty(deploymentPrincipalId)) {
  name: 'deploymentSecretsOfficer-${target.code}-${uniqueString(kvMain.name)}'
  scope: resourceGroup(target.subscriptionId, resourceGroups.main.name)
  params: {
    keyVaultName: kvMain.name
    principalId: deploymentPrincipalId
    roleDefinitionId: subscriptionResourceId(
      target.subscriptionId,
      'Microsoft.Authorization/roleDefinitions',
      keyVaultSecretsOfficerRoleId
    )
  }
  dependsOn: [
    kvMainModule
  ]
}

helpers.template:
targetScope = 'resourceGroup'

@description('Nom du Key Vault qui reçoit le rôle.')
param keyVaultName string

@description('Object ID du principal auquel le rôle est attribué.')
param principalId string

@description('ID de définition du rôle intégré.')
param roleDefinitionId string

var keyVaultSecretsOfficerRoleId = '{{role:Key Vault Secrets Officer}}'

resource keyVault '{{resource:KeyVault}}' existing = {
  name: keyVaultName
}

resource deploymentSecretsOfficer 'Microsoft.Authorization/roleAssignments@{{roleAssignmentApiVersion}}' = {
  name: guid(keyVault.id, principalId, keyVaultSecretsOfficerRoleId)
  scope: keyVault
  properties: {
    roleDefinitionId: roleDefinitionId
    principalId: principalId
    principalType: 'ServicePrincipal'
  }
}
